#[cfg(test)]
mod tests {
    use rust_human_session_stats::{sum, mean, min, max, median};

    // sum
    #[test]
    fn test_sum_basic() {
        assert_eq!(sum(&[1.0, 2.0, 3.0]), 6.0);
    }

    #[test]
    fn test_sum_empty() {
        assert_eq!(sum(&[]), 0.0);
    }

    // mean
    #[test]
    fn test_mean_basic() {
        assert_eq!(mean(&[2.0, 4.0, 6.0]), Some(4.0));
    }

    #[test]
    fn test_mean_empty() {
        assert_eq!(mean(&[]), None);
    }

    // min
    #[test]
    fn test_min_basic() {
        assert_eq!(min(&[3.0, 1.0, 4.0, 1.5]), Some(1.0));
    }

    #[test]
    fn test_min_empty() {
        assert_eq!(min(&[]), None);
    }

    // max
    #[test]
    fn test_max_basic() {
        assert_eq!(max(&[3.0, 1.0, 4.0, 1.5]), Some(4.0));
    }

    #[test]
    fn test_max_empty() {
        assert_eq!(max(&[]), None);
    }

    // median
    #[test]
    fn test_median_odd() {
        assert_eq!(median(&[3.0, 1.0, 2.0]), Some(2.0));
    }

    #[test]
    fn test_median_even() {
        // sorted: [1,2,3,4] -> (2+3)/2 = 2.5
        assert_eq!(median(&[4.0, 1.0, 3.0, 2.0]), Some(2.5));
    }

    #[test]
    fn test_median_empty() {
        assert_eq!(median(&[]), None);
    }
}
